require "rails_helper"

RSpec.describe Timekeeping::Handoff::MonolithStore, :without_transaction do
  it "loading the same checkpoint twice replaces a stray row and keeps equal counts and checksums" do
    connection = ActiveRecord::Base.connection
    insert_entry = lambda do |company_id|
      connection.select_value(<<~SQL.squish)
        INSERT INTO entries (company_id, version, project_id, user_id, work_date, duration, bill_status, created_at, updated_at)
        VALUES (#{company_id}, 3, 1, 1, '2026-01-05', 1.5, 'unbilled', now(), now()) RETURNING id
      SQL
    end
    store = described_class.new(connection: connection)
    kept_ids = [insert_entry.call(1), insert_entry.call(2)]
    checkpoint = store.export_checkpoint
    stray_id = insert_entry.call(1)
    expect(connection.select_values("SELECT id FROM entries ORDER BY id")).to eq(kept_ids + [stray_id])

    # "Load the same checkpoint twice and get equal counts and checksums; a row seeded before the load is gone afterwards."
    2.times do
      store.load_checkpoint(checkpoint)

      expect(connection.select_values("SELECT id FROM entries ORDER BY id")).to eq(kept_ids)
      reexported = store.export_checkpoint
      expect(reexported.digest).to eq(checkpoint.digest)
      expect(reexported.digest.fetch("entries").transform_values { |company| company[:count] }).to eq(1 => 1, 2 => 1)
    end
  end
end

require "rails_helper"

RSpec.describe Timekeeping::Handoff::MonolithStore, :without_transaction do
  it "a load that fails at the audit insert leaves every prepared table as it was" do
    connection = ActiveRecord::Base.connection
    seeded_id = connection.select_value(<<~SQL.squish)
      INSERT INTO entries (company_id, version, project_id, user_id, work_date, duration, bill_status, created_at, updated_at)
      VALUES (1, 2, 1, 1, '2026-01-05', 0.75, 'unbilled', now(), now()) RETURNING id
    SQL
    entries_before = connection.select_all("SELECT * FROM entries ORDER BY id").to_a
    expect(entries_before.map { |row| row["id"] }).to eq([seeded_id])
    sequence = connection.select_value("SELECT pg_get_serial_sequence('entries', 'id')")
    sequence_before = connection.select_all("SELECT last_value, is_called FROM #{sequence}").to_a

    now = Time.utc(2026, 1, 5, 9, 30, 0.123456r)
    new_entry = {
      "id" => seeded_id + 100, "company_id" => 1, "version" => 4, "project_id" => 1, "user_id" => 1,
      "agent_id" => nil, "work_date" => Date.new(2026, 1, 6), "duration" => 2.0, "note" => "",
      "bill_status" => "unbilled", "review_status" => "not_required", "locked" => false, "source" => "manual",
      "source_metadata" => {}, "external_run_id" => nil, "external_session_id" => nil, "proof_url" => nil,
      "proof_metadata" => {}, "discarded_at" => nil, "created_at" => now, "updated_at" => now
    }
    # This audit row names an entry the checkpoint does not carry, so the
    # composite foreign key refuses it after entries were already replaced.
    orphan_audit = {
      "id" => 1, "company_id" => 1, "entry_id" => seeded_id + 999, "actor_type" => "User", "actor_id" => 7,
      "action" => "create", "before" => nil, "after" => { "duration" => 2.0 }, "entry_created_at" => now,
      "created_at" => now
    }
    checkpoint = Timekeeping::Handoff::Checkpoint.build(
      tables: {
        "entries" => [new_entry], "reservations" => [], "invoice_operations" => [],
        "entry_audits" => [orphan_audit], "idempotency_records" => []
      }
    )

    # "A load that fails midway leaves the tables as they were."
    expect { described_class.new(connection: connection).load_checkpoint(checkpoint) }.to raise_error(StandardError)

    expect(connection.select_all("SELECT * FROM entries ORDER BY id").to_a).to eq(entries_before)
    expect(connection.select_value("SELECT count(*) FROM entry_audits")).to eq(0)
    expect(connection.select_all("SELECT last_value, is_called FROM #{sequence}").to_a).to eq(sequence_before)
  end
end

