RSpec.describe Timekeeping::Handoff::MonolithStore, :without_transaction do
  it "export load and export keep versions duration bits audit rows and receipt bodies unchanged" do
    connection = ActiveRecord::Base.connection
    duration = 0.1 + 0.2
    entry_id = connection.select_value(<<~SQL.squish)
      INSERT INTO entries (company_id, version, project_id, user_id, work_date, duration, bill_status, review_status, discarded_at, created_at, updated_at)
      VALUES (1, 7, 1, 1, '2026-01-05', #{connection.quote(duration)}, 'billed', 'approved',
              '2026-01-06 10:00:00.654321', '2026-01-05 09:00:00.123456', '2026-01-05 09:30:00.000001')
      RETURNING id
    SQL
    connection.execute(<<~SQL.squish)
      INSERT INTO entry_audits (company_id, entry_id, actor_type, actor_id, action, before, after, entry_created_at, created_at)
      VALUES (1, #{entry_id}, 'User', 42, 'update', '{"note": "a"}', '{"note": "b"}',
              '2026-01-05 09:00:00.123456', '2026-01-05 09:30:00.000001')
    SQL
    body = '{ "z": 1,  "a": [1.0, 2] }'
    [1, 2].each do |company_id|
      # No squish here: it would collapse the spacing inside the body literal.
      connection.execute(<<~SQL)
        INSERT INTO idempotency_records (company_id, actor_type, actor_id, operation, key, fingerprint, status, body, created_at)
        VALUES (#{company_id}, 'User', 42, 'create_entry', 'same-key', 'fp', 201, #{connection.quote(body)}, now())
      SQL
    end
    read_rows = lambda do
      {
        entries: connection.select_all("SELECT id, version, duration, created_at, updated_at, discarded_at FROM entries").to_a,
        audits: connection.select_all("SELECT * FROM entry_audits ORDER BY id").to_a,
        receipts: connection.select_all("SELECT * FROM idempotency_records ORDER BY company_id").to_a
      }
    end
    rows_before = read_rows.call
    expect(rows_before[:receipts].map { |row| [row["company_id"], row["body"]] }).to eq([[1, body], [2, body]])
    store = described_class.new(connection: connection)

    # "Entry versions and duration floats survive export and load unchanged, bit for bit"
    checkpoint = store.export_checkpoint
    store.load_checkpoint(checkpoint)

    expect(read_rows.call).to eq(rows_before)
    stored_duration = connection.select_value("SELECT duration FROM entries WHERE id = #{entry_id}")
    expect([stored_duration].pack("G")).to eq([duration].pack("G"))
    expect(connection.select_value("SELECT version FROM entries WHERE id = #{entry_id}")).to eq(7)
    expect(store.export_checkpoint.digest).to eq(checkpoint.digest)
  end
end

