RSpec.describe Timekeeping::Handoff::MonolithStore, :without_transaction do
  it "a load inside an open transaction is refused so committing that transaction keeps the original rows" do
    connection = ActiveRecord::Base.connection
    insert_entry = lambda do
      connection.select_value(<<~SQL.squish)
        INSERT INTO entries (company_id, version, project_id, user_id, work_date, duration, bill_status, created_at, updated_at)
        VALUES (1, 1, 1, 1, '2026-01-05', 1.0, 'unbilled', now(), now()) RETURNING id
      SQL
    end
    store = described_class.new(connection: connection)
    empty_checkpoint = store.export_checkpoint
    original_id = insert_entry.call
    expect(connection.select_values("SELECT id FROM entries")).to eq([original_id])

    # "load a checkpoint by replacing the store's tables in one transaction, recomputing the digest inside that transaction and rolling back on a mismatch"
    refused = false
    ActiveRecord::Base.transaction do
      store.load_checkpoint(empty_checkpoint)
    rescue StandardError
      refused = true
    end

    expect(refused).to be(true)
    expect(connection.select_values("SELECT id FROM entries")).to eq([original_id])
  end
end

require "rails_helper"

RSpec.describe Timekeeping::Handoff::MonolithStore, :without_transaction do
  it "advancing the entry id sequence below its value leaves it and above its value raises it" do
    connection = ActiveRecord::Base.connection
    insert_entry = lambda do
      connection.select_value(<<~SQL.squish)
        INSERT INTO entries (company_id, version, project_id, user_id, work_date, duration, bill_status, created_at, updated_at)
        VALUES (1, 1, 1, 1, '2026-01-05', 1.0, 'unbilled', now(), now()) RETURNING id
      SQL
    end
    store = described_class.new(connection: connection)
    sequence = connection.select_value("SELECT pg_get_serial_sequence('entries', 'id')")
    insert_entry.call
    current = insert_entry.call
    state_before = connection.select_all("SELECT last_value, is_called FROM #{sequence}").to_a

    # "A sequence only advances: it is set only if the new value is higher than its current one."
    store.advance_entry_id_sequence(above: current - 1)
    expect(connection.select_all("SELECT last_value, is_called FROM #{sequence}").to_a).to eq(state_before)
    store.advance_entry_id_sequence(above: current)
    expect(connection.select_all("SELECT last_value, is_called FROM #{sequence}").to_a).to eq(state_before)

    target = current + 1000
    store.advance_entry_id_sequence(above: target)
    expect(insert_entry.call).to eq(target + 1)
  end
end

